import React, { useState, useEffect } from 'react';
import axios from 'axios';

const PropertyList = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    // Component load hote hi backend se data fetch karenge
    const fetchProperties = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/properties/all');
        setProperties(response.data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load properties. Make sure backend is running.');
        setLoading(false);
      }
    };

    fetchProperties();
  }, []);

  if (loading) return <p style={{ textAlign: 'center' }}>Loading properties...</p>;
  if (error) return <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>;

  return (
    <div style={{ marginTop: '20px' }}>
      <h3 style={{ color: '#80608f' }}>Available PGs & Hostels</h3>
      
      {properties.length === 0 ? (
        <p>No properties found. Add some from the backend!</p>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
          {properties.map((pg) => (
            <div key={pg.id} style={{ 
              border: '1px solid #e6d9ef', 
              borderRadius: '8px', 
              padding: '15px',
              backgroundColor: '#fff',
              boxShadow: '0 2px 5px rgba(0,0,0,0.05)'
            }}>
              <h4 style={{ margin: '0 0 10px 0', color: '#4a4a4a' }}>{pg.pgName}</h4>
              <p style={{ margin: '5px 0' }}><strong>City:</strong> {pg.city}</p>
              <p style={{ margin: '5px 0' }}><strong>Rent:</strong> ₹{pg.rent}/month</p>
              <p style={{ margin: '5px 0' }}><strong>AC:</strong> {pg.hasAc ? 'Yes' : 'No'}</p>
              <p style={{ margin: '5px 0' }}><strong>Sharing:</strong> {pg.sharingType} Person</p>
              <p style={{ fontSize: '0.9em', color: '#666', marginTop: '10px' }}>{pg.description}</p>
              
              <button style={{ 
                marginTop: '15px', 
                padding: '8px 15px', 
                backgroundColor: '#80608f', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px',
                cursor: 'pointer',
                width: '100%'
              }}>
                View Details / Book
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default PropertyList;
